import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const { motion } = JSON.parse(readFileSync(resolve(root, 'packages/design-tokens/tokens.json'), 'utf8'));
const css = [
  '/* Generated by scripts/sync-motion.mjs from design-tokens/tokens.json. */',
  ':root {',
  ...Object.entries(motion.duration).map(([role, value]) => `  --motion-duration-${role}: ${value}ms;`),
  `  --motion-ease: ${motion.ease};`,
  `  --motion-settle: ${motion.settle};`,
  `  --motion-travel: ${motion.travel};`,
  '}',
  '/* Include pseudo-elements; keep completion events for dialogs and transitions. */',
  '@media (prefers-reduced-motion: reduce) {',
  '  *, *::before, *::after {',
  '    animation-duration: .01ms !important;',
  '    animation-delay: 0ms !important;',
  '    animation-iteration-count: 1 !important;',
  '    transition-duration: .01ms !important;',
  '    transition-delay: 0ms !important;',
  '    scroll-behavior: auto !important;',
  '  }',
  '}',
  '',
].join('\n');
const curve = (value) => value.slice(value.indexOf('(') + 1, -1);
const swift = `// Generated by scripts/sync-motion.mjs. Keep H5 and iOS motion in sync.
import SwiftUI

enum SharedMotionTokens {
    static let press = Animation.timingCurve(${curve(motion.ease)}, duration: ${motion.duration.fast / 1000})
    static let selection = Animation.timingCurve(${curve(motion.ease)}, duration: ${motion.duration.standard / 1000})
    static let reveal = Animation.timingCurve(${curve(motion.settle)}, duration: ${motion.duration.enter / 1000})
    static let exit = Animation.timingCurve(${curve(motion.ease)}, duration: ${motion.duration.exit / 1000})
}
`;
let drift = false;
const outputs = new Map([
  ['packages/design-tokens/motion.css', css],
  ['apps/web-h5/src/theme/motion-tokens.css', css],
  ['apps/ios-customer/DongFangApp/DesignSystem/SharedMotionTokens.swift', swift],
  ['apps/ios-master/MasterApp/DesignSystem/SharedMotionTokens.swift', swift],
]);
for (const [target, content] of outputs) {
  if (target.startsWith('apps/web-h5') && !existsSync(resolve(root, 'apps/web-h5/src'))) continue;
  const path = resolve(root, target);
  if (process.argv.includes('--check')) {
    if (!existsSync(path) || readFileSync(path, 'utf8') !== content) { console.error('Motion drift: ' + target); drift = true; }
  } else { writeFileSync(path, content); console.log('Generated ' + target); }
}
if (drift) process.exit(1);
